<?php
declare(strict_types=1); require __DIR__.'/includes/auth_guard.php';
$errors=[];$data=['bid'=>'','roomnum'=>'','floor'=>'','descriptionss'=>''];
if($_SERVER['REQUEST_METHOD']==='POST'){if(!verify_csrf($_POST['csrf_token']??null)){$errors[]='Invalid form token. Please try again.';}
$data=array_merge($data,$_POST);$bid=filter_var($_POST['bid']??null,FILTER_VALIDATE_INT);$room=trim((string)($_POST['roomnum']??''));$floor=trim((string)($_POST['floor']??''));$desc=trim((string)($_POST['descriptionss']??''));if($bid===false||$bid===null||$bid<1)$errors[]='Building ID must be a valid number.';elseif(!$buildingModel->exists($bid))$errors[]='The selected building does not exist.';if($room==='')$errors[]='Room number is required.';if($floor==='')$errors[]='Floor is required.';if(!$errors){try{$image=image_upload();if(!$image)throw new RuntimeException('Please choose an image.');$roomModel->create($bid,$room,$floor,$image,$desc);flash('success','Room created successfully.');redirect('new_buildingAdmin.php');}catch(Throwable $e){error_log($e->getMessage());if(isset($image))delete_uploaded_image($image);$errors[]='The room could not be created.';}}}
$pageTitle='Add Room';require __DIR__.'/includes/admin_header.php';
?><div class="admin-card form-card"><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><?php foreach($errors as $error):?><div class="alert alert-danger"><?=e($error)?></div><?php endforeach;?><div class="mb-3"><label class="form-label">Building ID</label><input class="form-control" type="number" min="1" name="bid" value="<?=e((string)$data['bid'])?>" required></div><div class="mb-3"><label class="form-label">Room number</label><input class="form-control" name="roomnum" value="<?=e((string)$data['roomnum'])?>" required></div><div class="mb-3"><label class="form-label">Floor</label><input class="form-control" name="floor" value="<?=e((string)$data['floor'])?>" required></div><div class="mb-3"><label class="form-label">Image</label><input class="form-control" type="file" name="image" accept="image/jpeg,image/png,image/gif,image/webp" required></div><div class="mb-3"><label class="form-label">Description</label><textarea class="form-control" name="descriptionss" rows="7"><?=e((string)$data['descriptionss'])?></textarea></div><button class="btn btn-success">Save</button> <a class="btn btn-secondary" href="new_buildingAdmin.php">Cancel</a></form></div><?php require __DIR__.'/includes/admin_footer.php';?>
